export default {async fetch(req,env){try{const p=new URL(req.url).pathname;if(p==='/assets/default-avatar.svg')return new Response('<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#382269"/><stop offset="1" stop-color="#0d3548"/></linearGradient></defs><rect width="512" height="512" fill="url(#g)"/><circle cx="256" cy="190" r="90" fill="#a99dd9"/><path d="M76 512v-35c0-178 360-178 360 0v35" fill="#779dc5"/></svg>',{headers:{'content-type':'image/svg+xml','cache-control':'public,max-age=86400'}});if(p==='/assets/profile-cover.webp')return new Response(req.method==='HEAD'?null:Uint8Array.from(atob(PROFILE_COVER),c=>c.charCodeAt(0)),{headers:{'content-type':'image/webp','cache-control':'public,max-age=86400','x-content-type-options':'nosniff'}});if(p.startsWith('/cover/')){const profile=await one(env.DB,'SELECT cover_id FROM wm_profile_details WHERE user_id=?',p.slice(7));need(profile?.cover_id,'Not found',404);const object=await env.MEDIA.get(profile.cover_id);need(object,'Not found',404);return new Response(req.method==='HEAD'?null:object.body,{headers:{'content-type':object.httpMetadata?.contentType||'image/jpeg','cache-control':'no-store','x-content-type-options':'nosniff'}})}if(p.startsWith('/avatar/')){need(['GET','HEAD'].includes(req.method),'Method not allowed',405);const profile=await one(env.DB,'SELECT picture_id FROM wm_profile_details WHERE user_id=?',p.slice(8));need(profile?.picture_id,'Not found',404);const object=await env.MEDIA.get(profile.picture_id);need(object,'Not found',404);return new Response(req.method==='HEAD'?null:object.body,{headers:{'content-type':object.httpMetadata?.contentType||'image/jpeg','cache-control':'no-store','x-content-type-options':'nosniff'}})}if(p.startsWith('/group-logo/')){const g=await one(env.DB,'SELECT logo_id FROM wm_groups WHERE id=?',p.slice(12));need(g?.logo_id,'Not found',404);const object=await env.MEDIA.get(g.logo_id);need(object,'Not found',404);return new Response(req.method==='HEAD'?null:object.body,{headers:{'content-type':object.httpMetadata?.contentType||'image/jpeg','cache-control':'no-store','x-content-type-options':'nosniff'}})}if(p.startsWith('/api/'))return await api(req,env);if(p.startsWith('/media/')){need(['GET','HEAD'].includes(req.method),'Method not allowed',405);const id=p.slice(7);need(/^[a-f0-9-]{36}$/.test(id),'Not found',404);const upload=await one(env.DB,'SELECT * FROM wm_uploads WHERE id=?',id);need(upload,'Not found',404);const publicPost=await one(env.DB,"SELECT id,group_id FROM wm_posts WHERE deleted_at IS NULL AND status='approved' AND EXISTS(SELECT 1 FROM json_each(media) WHERE json_extract(value,'$.id')=?) ORDER BY CASE WHEN group_id IS NULL THEN 0 ELSE 1 END LIMIT 1",id);const viewer=await user(req,env.DB)||await adminUser(req,env.DB);const chatMedia=viewer&&await one(env.DB,"SELECT id FROM wm_messages m WHERE m.user_id=? AND m.text=? AND m.deleted_at IS NULL AND m.archived_at IS NULL AND EXISTS(SELECT 1 FROM wm_threads t WHERE t.id=m.thread_id AND (t.buyer_id=? OR t.seller_id=?)) UNION ALL SELECT id FROM wm_group_messages m WHERE m.user_id=? AND m.text=? AND m.deleted_at IS NULL AND m.archived_at IS NULL AND EXISTS(SELECT 1 FROM wm_group_members gm WHERE gm.group_id=m.group_id AND gm.user_id=?) LIMIT 1",upload.user_id,'media:'+upload.type+':/media/'+id,viewer.id,viewer.id,upload.user_id,'media:'+upload.type+':/media/'+id,viewer.id);const groupLogo=await one(env.DB,'SELECT id FROM wm_groups WHERE logo_id=? LIMIT 1',id);if(!chatMedia&&!groupLogo&&(!publicPost||publicPost.group_id)){const u=viewer;need(u,'Not found',404);if(u.id!==upload.user_id){const moderation=trusted(u)&&await one(env.DB,"SELECT p.id FROM wm_posts p LEFT JOIN wm_groups g ON g.id=p.group_id WHERE EXISTS(SELECT 1 FROM json_each(p.media) WHERE json_extract(value,'$.id')=?) AND (?='owner' OR p.group_id IS NULL OR g.owner_id=?) LIMIT 1",id,u.role,u.id);need(moderation||(publicPost?.group_id&&await one(env.DB,'SELECT 1 FROM wm_group_members WHERE group_id=? AND user_id=?',publicPost.group_id,u.id)),'Not found',404)}}const object=await env.MEDIA.get(id,req.headers.has('range')?{range:req.headers}:undefined);need(object,'Not found',404);const headers={'content-type':upload.type,'cache-control':'private,no-store','x-content-type-options':'nosniff','accept-ranges':'bytes','content-disposition':'inline'};if(req.headers.has('range')&&object.range){headers['content-range']='bytes '+object.range.offset+'-'+(object.range.offset+object.range.length-1)+'/'+object.size;headers['content-length']=String(object.range.length)}return new Response(req.method==='HEAD'?null:object.body,{status:req.headers.has('range')&&object.range?206:200,headers})}if((p==='/admin'||p==='/admin/')&&['GET','HEAD'].includes(req.method))return new Response(req.method==='HEAD'?null:ADMIN_PAGE,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'no-referrer'}});if((p==='/'||p==='/index.html'||/^\/post\/[a-f0-9-]{36}$/.test(p)||/^\/u\/[a-z][a-z0-9_]{2,23}$/.test(p))&&['GET','HEAD'].includes(req.method))return new Response(req.method==='HEAD'?null:PAGE,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin','cross-origin-opener-policy':'same-origin-allow-popups'}});return reply({error:'Not found'},404)}catch(e){if(!(e instanceof HttpError))console.error(JSON.stringify({event:'request_failed',path:new URL(req.url).pathname}));return reply({error:e instanceof HttpError?e.message:'Server error. Try again shortly.'},e.status||500)}}};


